/**
 * Build and verify the launcher APKs (debug and release).
 *
 *   bun run android:build
 *
 * Inputs are checked first (scripts/android-build-preflight.ts): the pinned
 * checkout, the staged on-device voice outputs, the prepared runtime source and the
 * staged resident runtime. `bun run android:build:local` prepares and stages the
 * runtime before calling this script. The Gradle host is generated by the pinned
 * upstream consumer-host generator from android/consumer-host.json
 * (scripts/android-host.ts) before Gradle runs.
 *
 * The build is always flag-off: ELIZA_DEV_ALLOW_TEST_MOCKS and its VITE_ mirror are
 * removed from every child environment, whatever the caller exported. Outputs go to
 * artifacts/.
 */
import { execFileSync, spawnSync } from "node:child_process";
import type { ExecFileSyncOptionsWithBufferEncoding } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {readUpdateChannel} from './update-channel.ts';
import type {UpdateChannel} from './update-channel.ts';


type BuildCommand = (command: string, args: string[], extra?: ExecFileSyncOptionsWithBufferEncoding) => unknown;

const FLAG = "ELIZA_DEV_ALLOW_TEST_MOCKS";
const FLAG_ENV_NAMES = [FLAG, `VITE_${FLAG}`, `ORG_GRADLE_PROJECT_${FLAG}`];
/**
 * The release-signing environment names the generated Gradle host reads
 * (android/consumer-host.json, profile.signing): store file, store password,
 * key alias and key password. Only names are recorded; the human signer
 * supplies the values when building a release.
 */
export const SIGNING_ENV = (() => {
  const signing: Record<string, unknown> | undefined = JSON.parse(fs.readFileSync(new URL("../android/consumer-host.json", import.meta.url), "utf8")).profile.signing;
  const names = ["storeFile", "storePassword", "keyAlias", "keyPassword"]
    .map(key => signing?.[key])
    .filter((name): name is string => typeof name === "string" && /^[A-Z][A-Z0-9_]*$/.test(name));
  if (new Set(names).size !== 4)
    throw new Error("android/consumer-host.json must name four release-signing environment variables");
  return Object.freeze(names);
})();
const USAGE = "Usage: bun run android:build";

export function parseBuildArgs(argv: readonly string[]) {
  for (const arg of argv) throw new Error(`Unknown option ${arg}. ${USAGE}`);
}

/** Child environment for a build: the browser development mock switch never reaches it. */
export function buildEnv(base: NodeJS.ProcessEnv) {
  const env: NodeJS.ProcessEnv = { ...base };
  for (const name of FLAG_ENV_NAMES) delete env[name];
  return env;
}

const signingValue = (env: NodeJS.ProcessEnv, name: string) => {
  const value = env[name];
  return typeof value === "string" && value.trim() !== "";
};
export const signingRequested = (env: NodeJS.ProcessEnv) => SIGNING_ENV.every(name => signingValue(env, name));

/** Names (never values) of the signing variables a partial ELIZAOS_* set lacks; null when none or all are set. */
export function partialSigningProblem(env: NodeJS.ProcessEnv) {
  const missing = SIGNING_ENV.filter(name => !signingValue(env, name));
  if (missing.length === 0 || missing.length === SIGNING_ENV.length) return null;
  return `Incomplete release signing environment: missing ${missing.join(", ")}. Set all of ${SIGNING_ENV.join(", ")} or none.`;
}

export const RELEASE_SIGNER_FILE = "android/release-signer.json";
const hex64 = /^[0-9a-f]{64}$/;

export interface ReleaseSigner {
  schema: 1;
  signerSha256: string;
  lastRelease: {
    versionCode: number | null;
    versionName?: unknown;
    recordedAt?: unknown;
  };
}

interface ReleaseIdentity {
  signed: boolean;
  signerSha256?: string | null;
  versionCode: number | null;
}

/** Validate the fields used to admit the committed release-signer descriptor. */
export function validateReleaseSigner(input: unknown): ReleaseSigner {
  const descriptor = input && typeof input === "object" ? input as Record<string, unknown> : null;
  const problems: string[] = [];
  if (descriptor?.schema !== 1) problems.push("schema must be 1");
  const signer = descriptor?.signerSha256;
  if (signer !== "unset" && !(typeof signer === "string" && hex64.test(signer)))
    problems.push("signerSha256 must be 'unset' or a lowercase 64-hex certificate digest");
  const last = descriptor?.lastRelease;
  if (!last || typeof last !== "object") problems.push("lastRelease is required");
  else {
    const version = (last as Record<string, unknown>).versionCode;
    if (version !== null && !(typeof version === "number" && Number.isInteger(version) && version > 0))
      problems.push("lastRelease.versionCode must be null or a positive integer");
  }
  if (problems.length) throw new Error(`${RELEASE_SIGNER_FILE} is invalid: ${problems.join("; ")}`);
  return input as ReleaseSigner;
}

export function readReleaseSigner(root = process.cwd()) {
  return validateReleaseSigner(JSON.parse(fs.readFileSync(path.join(root, RELEASE_SIGNER_FILE), "utf8")));
}

/**
 * Release admission against the descriptor. `failures` stop verification (a signed
 * release with a different certificate or a non-advancing versionCode); `blockers`
 * keep an otherwise valid release distributable:false (unsigned, signer unset,
 * an unsigned build that does not advance the recorded versionCode).
 */
export function releaseAdmission({ signed, signerSha256, versionCode }: ReleaseIdentity, input: unknown,
  { installedReadback = false } = {}) {
  const descriptor = validateReleaseSigner(input);
  const failures: string[] = [];
  const blockers: string[] = [];
  if (!signed) blockers.push("unsigned release");
  if (descriptor.signerSha256 === "unset") blockers.push(`release signer is unset in ${RELEASE_SIGNER_FILE}`);
  else if (signed && signerSha256 !== descriptor.signerSha256)
    failures.push(`release signer ${signerSha256 ?? "unknown"} does not match ${RELEASE_SIGNER_FILE} ${descriptor.signerSha256}`);
  const last = descriptor.lastRelease.versionCode;
  if (!installedReadback && last !== null && !(versionCode !== null && Number.isInteger(versionCode) && versionCode > last)) {
    const message = `versionCode ${versionCode} is not greater than the last recorded release ${last}`;
    (signed ? failures : blockers).push(message);
  }
  const signerMatches = signed && descriptor.signerSha256 !== "unset" && signerSha256 === descriptor.signerSha256;
  return { failures, blockers, signerMatches };
}

/**
 * The SBOM written beside the APKs: the source pins, the APKs verify-apks just recorded and,
 * when a resident runtime is staged in this checkout, that payload. Offline; it lists what was
 * built and never changes a distributable verdict.
 */
export function sbomArgs(outDir: string, root = process.cwd()) {
  const staged = fs.existsSync(path.join(root, "android/app/src/main/assets/agent/agent-bundle.js"));
  return ["--out", path.join(outDir, "sbom", "alphaphone.cdx.json"), "--apks", outDir, ...(staged ? ["--packaged-runtime"] : [])];
}

const OUTPUT = "artifacts";

async function main() {
  parseBuildArgs(process.argv.slice(2));
  const channel=readUpdateChannel(process.env,JSON.parse(fs.readFileSync(new URL('../app.config.json',import.meta.url),'utf8')).updateManifestUrl);
  // A partial signing set would silently produce unsigned releases; refuse it up front.
  const partial = partialSigningProblem(process.env);
  if (partial) throw new Error(partial);
  // Report missing inputs (pinned checkout, voice outputs, prepared and staged runtime)
  // with the exact command to run, before web sync and a long Gradle build.
  const preflight = spawnSync(process.execPath, [path.join(import.meta.dirname, "android-build-preflight.ts")], { stdio: "inherit" });
  if (preflight.status !== 0) process.exit(preflight.status ?? 1);
  // A malformed release-signer descriptor fails before the long build, not after it.
  readReleaseSigner();
  // The toolchain resolver and the build orchestration live in the pinned checkout, which the preflight verified.
  const { androidEnv } = await import("./toolchain.ts");
  const { buildAndroidConsumer } = await import("../vendor/eliza/packages/app/scripts/mobile/android/build-consumer.mjs");
  const env = buildEnv(androidEnv());
  const run: BuildCommand = (cmd, args, extra = {}) =>
    execFileSync(cmd, args, { stdio: "inherit", env, ...extra });
  // The upstream JS default of null for androidTestOutput is inferred too narrowly.
  const buildConsumer = buildAndroidConsumer as unknown as (options: ReturnType<typeof consumerBuildOptions>) => unknown;
  console.log(`Android build: launcher, test mocks off -> ${OUTPUT}/`);

  run("bun", ["scripts/verify-upstream.ts"]);
  // The pinned upstream generator writes the Gradle host from android/consumer-host.json.
  run("bun", ["scripts/android-host.ts"]);
  run("bun", ["run", "android:sync"]);
  // The packaged web bundle must be flag-off before Gradle runs.
  const flags = JSON.parse(fs.readFileSync("web-dist/build-flags.json", "utf8"));
  if (flags.testMocks !== false) throw new Error(`web-dist/build-flags.json records testMocks=${flags.testMocks}; the APK packages only a flag-off bundle`);

  const root = fs.realpathSync(path.resolve(import.meta.dirname, ".."));
  buildConsumer(consumerBuildOptions(env, root, channel));
  run("bun", ["scripts/generate-sbom.ts", ...sbomArgs(OUTPUT, root)]);
}

/**
 * What the upstream consumer build receives. Upstream owns the Gradle invocation and artifact
 * collection: the debug and release launcher APKs (a signed release keeps `launcher-release.apk`),
 * the instrumentation APK and the R8 mapping. Alpha supplies the output directory, signing variable
 * names, build record and its own APK verification.
 */
export function consumerBuildOptions(env: NodeJS.ProcessEnv, root: string, updateChannel: UpdateChannel = readUpdateChannel(env, JSON.parse(fs.readFileSync(new URL('../app.config.json',import.meta.url),'utf8')).updateManifestUrl)) {
  return {
    root,
    environment: env,
    variants: ["launcher"],
    project: "android",
    output: OUTPUT,
    // The instrumentation APK lives in a subdirectory so artifacts/*.apk stays the app APKs
    // (scripts/android-instrumentation.ts).
    androidTestOutput: "instrumentation",
    signing: { environment: [...SIGNING_ENV] },
    mappings: true,
    // verify-apks compares this record with the APKs it verifies. Upstream writes it only after
    // every APK of this build is in place, so a failed build keeps the previous APKs and record.
    record: {
      name: "build-config.json",
      metadata: {
        createdAt: new Date().toISOString(),
        // Constants since the test-mocks APK and the Cloud profile were removed; record readers still expect the fields.
        testMocks: false,
        runtimeProfile: "native",
        updateChannel,
        mapsProvider: "cloud",
        signingRequested: signingRequested(env),
        versionOverride: { code: env.ELIZAOS_VERSION_CODE ?? null, name: env.ELIZAOS_VERSION_NAME ?? null },
      },
    },
    verify: { command: "bun", args: ["scripts/verify-apks.ts"] },
    archive: null,
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
